    # Find the full-width and full-height separator lines.
    row_sep = next((r for r, row in enumerate(grid)
                    if len(set(row)) == 1 and row[0] != 0), None)
    col_sep = next((c for c in range(w)
                    if len({grid[r][c] for r in range(h)}) == 1
                    and grid[0][c] != 0), None)

    if row_sep is None or col_sep is None:
        return [row[:] for row in grid]

    tile_h, tile_w = row_sep, col_sep
    sep_color = grid[row_sep][0]
    out = [[0] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if r % (tile_h + 1) == tile_h or c % (tile_w + 1) == tile_w:
                out[r][c] = sep_color
