def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate uniform separator lines.
    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != 0]

    sr = sep_rows[0] if sep_rows else None
    sc = sep_cols[0] if sep_cols else None

    # In each direction, use the nonblank region adjoining a separator as
    # the motif, then tile it across the grid. A single separator bounds the
    # motif on its preceding side; repeated separators bound it on both sides.
    if sc is not None:
        stride_c = (sep_cols[1] - sep_cols[0]) if len(sep_cols) > 1 else sc + 1
        if len(sep_cols) > 1:
            c0 = sc + 1
        else:
            c0 = 0
        motif_w = stride_c - 1
    else:
        c0, motif_w, stride_c = 0, w, w

    if sr is not None:
        stride_r = (sep_rows[1] - sep_rows[0]) if len(sep_rows) > 1 else sr + 1
        r0 = sr + 1 if len(sep_rows) > 1 else 0
        motif_h = stride_r - 1
    else:
        r0, motif_h, stride_r = 0, h, h

    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if (r in sep_rows) or (c in sep_cols):
                out[r][c] = grid[r][c]
            else:
                rr = r0 + ((r - r0) % stride_r)
                cc = c0 + ((c - c0) % stride_c)
                if rr >= r0 + motif_h:
                    rr = r0 + (rr - r0) % motif_h
                if cc >= c0 + motif_w:
                    cc = c0 + (cc - c0) % motif_w
                out[r][c] = grid[rr][cc]
    return out
